/* Faithful Rust translation of dcn20_mpc.c. External types, registers, and
 * helper macros are supplied by the surrounding driver translation. */

pub unsafe fn mpc2_update_blending(mpc: *mut mpc, blnd_cfg: *mut mpcc_blnd_cfg, mpcc_id: i32) {
    let mpc20 = TO_DCN20_MPC(mpc);
    let mpcc = mpc1_get_mpcc(mpc, mpcc_id);
    REG_UPDATE_7!(mpc20, MPCC_CONTROL[mpcc_id], MPCC_ALPHA_BLND_MODE, (*blnd_cfg).alpha_mode, MPCC_ALPHA_MULTIPLIED_MODE, (*blnd_cfg).pre_multiplied_alpha, MPCC_BLND_ACTIVE_OVERLAP_ONLY, (*blnd_cfg).overlap_only, MPCC_GLOBAL_ALPHA, (*blnd_cfg).global_alpha, MPCC_GLOBAL_GAIN, (*blnd_cfg).global_gain, MPCC_BG_BPC, (*blnd_cfg).background_color_bpc, MPCC_BOT_GAIN_MODE, (*blnd_cfg).bottom_gain_mode);
    REG_SET!(mpc20, MPCC_TOP_GAIN[mpcc_id], 0, MPCC_TOP_GAIN, (*blnd_cfg).top_gain);
    REG_SET!(mpc20, MPCC_BOT_GAIN_INSIDE[mpcc_id], 0, MPCC_BOT_GAIN_INSIDE, (*blnd_cfg).bottom_inside_gain);
    REG_SET!(mpc20, MPCC_BOT_GAIN_OUTSIDE[mpcc_id], 0, MPCC_BOT_GAIN_OUTSIDE, (*blnd_cfg).bottom_outside_gain);
    (*mpcc).blnd_cfg = *blnd_cfg;
}

pub unsafe fn mpc2_set_denorm(mpc: *mut mpc, opp_id: i32, output_depth: dc_color_depth) {
    let mpc20 = TO_DCN20_MPC(mpc); let mut denorm_mode = 0;
    match output_depth { COLOR_DEPTH_666 => denorm_mode=1, COLOR_DEPTH_888=>denorm_mode=2, COLOR_DEPTH_999=>denorm_mode=3, COLOR_DEPTH_101010=>denorm_mode=4, COLOR_DEPTH_111111=>denorm_mode=5, COLOR_DEPTH_121212=>denorm_mode=6, COLOR_DEPTH_141414 | COLOR_DEPTH_161616 => (), _ => () }
    REG_UPDATE!(mpc20, DENORM_CONTROL[opp_id], MPC_OUT_DENORM_MODE, denorm_mode);
}

pub unsafe fn mpc2_set_denorm_clamp(mpc: *mut mpc, opp_id: i32, denorm_clamp: mpc_denorm_clamp) {
    let mpc20 = TO_DCN20_MPC(mpc);
    REG_UPDATE_2!(mpc20, DENORM_CONTROL[opp_id], MPC_OUT_DENORM_CLAMP_MAX_R_CR, denorm_clamp.clamp_max_r_cr, MPC_OUT_DENORM_CLAMP_MIN_R_CR, denorm_clamp.clamp_min_r_cr);
    REG_UPDATE_2!(mpc20, DENORM_CLAMP_G_Y[opp_id], MPC_OUT_DENORM_CLAMP_MAX_G_Y, denorm_clamp.clamp_max_g_y, MPC_OUT_DENORM_CLAMP_MIN_G_Y, denorm_clamp.clamp_min_g_y);
    REG_UPDATE_2!(mpc20, DENORM_CLAMP_B_CB[opp_id], MPC_OUT_DENORM_CLAMP_MAX_B_CB, denorm_clamp.clamp_max_b_cb, MPC_OUT_DENORM_CLAMP_MIN_B_CB, denorm_clamp.clamp_min_b_cb);
}

pub unsafe fn mpc2_set_output_csc(mpc: *mut mpc, opp_id: i32, regval: *const u16, mut ocsc_mode: mpc_output_csc_mode) {
    let mpc20 = TO_DCN20_MPC(mpc); let mut cur_mode=0; let mut ocsc_regs = color_matrices_reg::default();
    if ocsc_mode == MPC_OUTPUT_CSC_DISABLE { REG_SET!(mpc20, CSC_MODE[opp_id],0,MPC_OCSC_MODE,ocsc_mode); return; }
    if regval.is_null() { BREAK_TO_DEBUGGER!(); return; }
    IX_REG_GET!(mpc20, MPC_OCSC_TEST_DEBUG_INDEX,MPC_OCSC_TEST_DEBUG_DATA,MPC_OCSC_TEST_DEBUG_DATA_STATUS_IDX,MPC_OCSC_TEST_DEBUG_DATA_OCSC_MODE,&mut cur_mode);
    ocsc_mode = if cur_mode != MPC_OUTPUT_CSC_COEF_A { MPC_OUTPUT_CSC_COEF_A } else { MPC_OUTPUT_CSC_COEF_B };
    ocsc_regs.shifts.csc_c11=(*mpc20).mpc_shift.MPC_OCSC_C11_A; ocsc_regs.masks.csc_c11=(*mpc20).mpc_mask.MPC_OCSC_C11_A; ocsc_regs.shifts.csc_c12=(*mpc20).mpc_shift.MPC_OCSC_C12_A; ocsc_regs.masks.csc_c12=(*mpc20).mpc_mask.MPC_OCSC_C12_A;
    if ocsc_mode == MPC_OUTPUT_CSC_COEF_A { ocsc_regs.csc_c11_c12=REG!(mpc20,CSC_C11_C12_A[opp_id]); ocsc_regs.csc_c33_c34=REG!(mpc20,CSC_C33_C34_A[opp_id]); } else { ocsc_regs.csc_c11_c12=REG!(mpc20,CSC_C11_C12_B[opp_id]); ocsc_regs.csc_c33_c34=REG!(mpc20,CSC_C33_C34_B[opp_id]); }
    cm_helper_program_color_matrices((*mpc20).base.ctx,regval,&mut ocsc_regs); REG_SET!(mpc20,CSC_MODE[opp_id],0,MPC_OCSC_MODE,ocsc_mode);
}

pub unsafe fn mpc2_set_ocsc_default(mpc:*mut mpc,opp_id:i32,color_space:dc_color_space,mut ocsc_mode:mpc_output_csc_mode){ let mut n=0; let m=TO_DCN20_MPC(mpc); if ocsc_mode==MPC_OUTPUT_CSC_DISABLE{REG_SET!(m,CSC_MODE[opp_id],0,MPC_OCSC_MODE,ocsc_mode);return;} let r=find_color_matrix(color_space,&mut n); if r.is_null(){BREAK_TO_DEBUGGER!();return;} let mut c=0; IX_REG_GET!(m,MPC_OCSC_TEST_DEBUG_INDEX,MPC_OCSC_TEST_DEBUG_DATA,MPC_OCSC_TEST_DEBUG_DATA_STATUS_IDX,MPC_OCSC_TEST_DEBUG_DATA_OCSC_MODE,&mut c); ocsc_mode=if c!=MPC_OUTPUT_CSC_COEF_A{MPC_OUTPUT_CSC_COEF_A}else{MPC_OUTPUT_CSC_COEF_B}; let mut o=color_matrices_reg::default(); o.shifts.csc_c11=(*m).mpc_shift.MPC_OCSC_C11_A;o.masks.csc_c11=(*m).mpc_mask.MPC_OCSC_C11_A;o.shifts.csc_c12=(*m).mpc_shift.MPC_OCSC_C12_A;o.masks.csc_c12=(*m).mpc_mask.MPC_OCSC_C12_A;if ocsc_mode==MPC_OUTPUT_CSC_COEF_A{o.csc_c11_c12=REG!(m,CSC_C11_C12_A[opp_id]);o.csc_c33_c34=REG!(m,CSC_C33_C34_A[opp_id]);}else{o.csc_c11_c12=REG!(m,CSC_C11_C12_B[opp_id]);o.csc_c33_c34=REG!(m,CSC_C33_C34_B[opp_id]);}cm_helper_program_color_matrices((*m).base.ctx,r,&mut o);REG_SET!(m,CSC_MODE[opp_id],0,MPC_OCSC_MODE,ocsc_mode); }

unsafe fn mpc2_ogam_get_reg_field(mpc:*mut mpc,reg:*mut xfer_func_reg){let m=TO_DCN20_MPC(mpc);(*reg).shifts.exp_region0_lut_offset=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION0_LUT_OFFSET;(*reg).masks.exp_region0_lut_offset=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION0_LUT_OFFSET;(*reg).shifts.exp_region0_num_segments=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION0_NUM_SEGMENTS;(*reg).masks.exp_region0_num_segments=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION0_NUM_SEGMENTS;(*reg).shifts.exp_region1_lut_offset=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION1_LUT_OFFSET;(*reg).masks.exp_region1_lut_offset=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION1_LUT_OFFSET;(*reg).shifts.exp_region1_num_segments=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION1_NUM_SEGMENTS;(*reg).masks.exp_region1_num_segments=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION1_NUM_SEGMENTS;(*reg).shifts.field_region_end=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION_END_B;(*reg).masks.field_region_end=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION_END_B;(*reg).shifts.field_region_end_slope=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION_END_SLOPE_B;(*reg).masks.field_region_end_slope=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION_END_SLOPE_B;(*reg).shifts.field_region_end_base=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION_END_BASE_B;(*reg).masks.field_region_end_base=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION_END_BASE_B;(*reg).shifts.field_region_linear_slope=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION_LINEAR_SLOPE_B;(*reg).masks.field_region_linear_slope=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION_LINEAR_SLOPE_B;(*reg).shifts.exp_region_start=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION_START_B;(*reg).masks.exp_region_start=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION_START_B;(*reg).shifts.exp_resion_start_segment=(*m).mpc_shift.MPCC_OGAM_RAMA_EXP_REGION_START_SEGMENT_B;(*reg).masks.exp_resion_start_segment=(*m).mpc_mask.MPCC_OGAM_RAMA_EXP_REGION_START_SEGMENT_B;}

pub unsafe fn mpc20_power_on_ogam_lut(mpc:*mut mpc,id:i32,on:bool){let m=TO_DCN20_MPC(mpc);REG_SET!(m,MPCC_MEM_PWR_CTRL[id],0,MPCC_OGAM_MEM_PWR_DIS,if on{1}else{0});}
unsafe fn mpc20_configure_ogam_lut(mpc:*mut mpc,id:i32,a:bool){let m=TO_DCN20_MPC(mpc);REG_UPDATE_2!(m,MPCC_OGAM_LUT_RAM_CONTROL[id],MPCC_OGAM_LUT_WRITE_EN_MASK,7,MPCC_OGAM_LUT_RAM_SEL,if a{0}else{1});REG_SET!(m,MPCC_OGAM_LUT_INDEX[id],0,MPCC_OGAM_LUT_INDEX,0);}
unsafe fn mpc20_get_ogam_current(mpc:*mut mpc,id:i32)->dc_lut_mode{let m=TO_DCN20_MPC(mpc);let mut s=0;REG_GET!(m,MPCC_OGAM_LUT_RAM_CONTROL[id],MPCC_OGAM_CONFIG_STATUS,&mut s);match s{0=>LUT_BYPASS,1=>LUT_RAM_A,2=>LUT_RAM_B,_=>LUT_BYPASS}}

unsafe fn mpc2_program_lutb(mpc:*mut mpc,id:i32,p:*const pwl_params){let m=TO_DCN20_MPC(mpc);let mut g=xfer_func_reg::default();mpc2_ogam_get_reg_field(mpc,&mut g);g.start_cntl_b=REG!(m,MPCC_OGAM_RAMB_START_CNTL_B[id]);g.start_cntl_g=REG!(m,MPCC_OGAM_RAMB_START_CNTL_G[id]);g.start_cntl_r=REG!(m,MPCC_OGAM_RAMB_START_CNTL_R[id]);g.start_slope_cntl_b=REG!(m,MPCC_OGAM_RAMB_SLOPE_CNTL_B[id]);g.start_slope_cntl_g=REG!(m,MPCC_OGAM_RAMB_SLOPE_CNTL_G[id]);g.start_slope_cntl_r=REG!(m,MPCC_OGAM_RAMB_SLOPE_CNTL_R[id]);g.start_end_cntl1_b=REG!(m,MPCC_OGAM_RAMB_END_CNTL1_B[id]);g.start_end_cntl2_b=REG!(m,MPCC_OGAM_RAMB_END_CNTL2_B[id]);g.start_end_cntl1_g=REG!(m,MPCC_OGAM_RAMB_END_CNTL1_G[id]);g.start_end_cntl2_g=REG!(m,MPCC_OGAM_RAMB_END_CNTL2_G[id]);g.start_end_cntl1_r=REG!(m,MPCC_OGAM_RAMB_END_CNTL1_R[id]);g.start_end_cntl2_r=REG!(m,MPCC_OGAM_RAMB_END_CNTL2_R[id]);g.region_start=REG!(m,MPCC_OGAM_RAMB_REGION_0_1[id]);g.region_end=REG!(m,MPCC_OGAM_RAMB_REGION_32_33[id]);cm_helper_program_xfer_func((*m).base.ctx,p,&mut g);}

unsafe fn mpc2_program_luta(mpc:*mut mpc,id:i32,p:*const pwl_params){let m=TO_DCN20_MPC(mpc);let mut g=xfer_func_reg::default();mpc2_ogam_get_reg_field(mpc,&mut g);g.start_cntl_b=REG!(m,MPCC_OGAM_RAMA_START_CNTL_B[id]);g.start_cntl_g=REG!(m,MPCC_OGAM_RAMA_START_CNTL_G[id]);g.start_cntl_r=REG!(m,MPCC_OGAM_RAMA_START_CNTL_R[id]);g.start_slope_cntl_b=REG!(m,MPCC_OGAM_RAMA_SLOPE_CNTL_B[id]);g.start_slope_cntl_g=REG!(m,MPCC_OGAM_RAMA_SLOPE_CNTL_G[id]);g.start_slope_cntl_r=REG!(m,MPCC_OGAM_RAMA_SLOPE_CNTL_R[id]);g.start_end_cntl1_b=REG!(m,MPCC_OGAM_RAMA_END_CNTL1_B[id]);g.start_end_cntl2_b=REG!(m,MPCC_OGAM_RAMA_END_CNTL2_B[id]);g.start_end_cntl1_g=REG!(m,MPCC_OGAM_RAMA_END_CNTL1_G[id]);g.start_end_cntl2_g=REG!(m,MPCC_OGAM_RAMA_END_CNTL2_G[id]);g.start_end_cntl1_r=REG!(m,MPCC_OGAM_RAMA_END_CNTL1_R[id]);g.start_end_cntl2_r=REG!(m,MPCC_OGAM_RAMA_END_CNTL2_R[id]);g.region_start=REG!(m,MPCC_OGAM_RAMA_REGION_0_1[id]);g.region_end=REG!(m,MPCC_OGAM_RAMA_REGION_32_33[id]);cm_helper_program_xfer_func((*m).base.ctx,p,&mut g);}

unsafe fn mpc20_program_ogam_pwl(mpc:*mut mpc,id:i32,rgb:*const pwl_result_data,num:u32){let m=TO_DCN20_MPC(mpc);PERF_TRACE!();for i in 0..num{let x=*rgb.add(i as usize);for v in [x.red_reg,x.green_reg,x.blue_reg,x.delta_red_reg,x.delta_green_reg,x.delta_blue_reg]{REG_SET!(m,MPCC_OGAM_LUT_DATA[id],0,MPCC_OGAM_LUT_DATA,v);}}PERF_TRACE!();}

unsafe fn apply_DEDCN20_305_wa(mpc:*mut mpc,id:i32,current:dc_lut_mode,next:dc_lut_mode){let m=TO_DCN20_MPC(mpc);if (*mpc).ctx.dc.debug.cm_in_bypass{REG_SET!(m,MPCC_OGAM_MODE[id],0,MPCC_OGAM_MODE,0);return;}if !(*mpc).ctx.dc.work_arounds.dedcn20_305_wa{return;}if current==LUT_BYPASS{REG_SET!(m,MPCC_OGAM_MODE[id],0,MPCC_OGAM_MODE,if next==LUT_RAM_A{1}else{2});}}

pub unsafe fn mpc2_set_output_gamma(mpc:*mut mpc,id:i32,p:*const pwl_params){let m=TO_DCN20_MPC(mpc);if (*mpc).ctx.dc.debug.cm_in_bypass||p.is_null(){REG_SET!(m,MPCC_OGAM_MODE[id],0,MPCC_OGAM_MODE,0);return;}let c=mpc20_get_ogam_current(mpc,id);let n=if c==LUT_BYPASS||c==LUT_RAM_A{LUT_RAM_B}else{LUT_RAM_A};mpc20_power_on_ogam_lut(mpc,id,true);mpc20_configure_ogam_lut(mpc,id,n==LUT_RAM_A);if n==LUT_RAM_A{mpc2_program_luta(mpc,id,p);}else{mpc2_program_lutb(mpc,id,p);}apply_DEDCN20_305_wa(mpc,id,c,n);mpc20_program_ogam_pwl(mpc,id,(*p).rgb_resulted,(*p).hw_points_num);REG_SET!(m,MPCC_OGAM_MODE[id],0,MPCC_OGAM_MODE,if n==LUT_RAM_A{1}else{2});}

pub unsafe fn mpc2_assert_idle_mpcc(mpc:*mut mpc,id:i32){let m=TO_DCN20_MPC(mpc);let mut d=0;ASSERT!((*m).mpcc_in_use_mask & (1<<id)==0);REG_GET!(m,MPCC_STATUS[id],MPCC_DISABLED,&mut d);if d!=0{return;}REG_WAIT!(m,MPCC_STATUS[id],MPCC_IDLE,1,1,100000);}
pub unsafe fn mpc2_assert_mpcc_idle_before_connect(mpc:*mut mpc,id:i32){let m=TO_DCN20_MPC(mpc);let(mut top,mut busy,mut idle,mut dis)=(0,0,0,0);REG_GET!(m,MPCC_TOP_SEL[id],MPCC_TOP_SEL,&mut top);REG_GET_3!(m,MPCC_STATUS[id],MPCC_BUSY,&mut busy,MPCC_IDLE,&mut idle,MPCC_DISABLED,&mut dis);if top==0xf{ASSERT!(busy==0);ASSERT!(idle!=0);ASSERT!(dis!=0);}else{ASSERT!(dis==0);ASSERT!(idle==0);}}

unsafe fn mpc2_init_mpcc(x:*mut mpcc,i:i32){(*x).mpcc_id=i;(*x).dpp_id=0xf;(*x).mpcc_bot=core::ptr::null_mut();(*x).blnd_cfg.overlap_only=false;(*x).blnd_cfg.global_alpha=0xff;(*x).blnd_cfg.global_gain=0xff;(*x).blnd_cfg.background_color_bpc=4;(*x).blnd_cfg.bottom_gain_mode=0;(*x).blnd_cfg.top_gain=0x1f000;(*x).blnd_cfg.bottom_inside_gain=0x1f000;(*x).blnd_cfg.bottom_outside_gain=0x1f000;(*x).sm_cfg.enable=false;}
unsafe fn mpc2_get_mpcc_for_dpp(t:*mut mpc_tree,d:i32)->*mut mpcc{let mut x=(*t).opp_list;while !x.is_null(){if (*x).dpp_id==0xf||(*x).dpp_id==d{return x;}ASSERT!(x!=(*x).mpcc_bot);if x==(*x).mpcc_bot{break;}x=(*x).mpcc_bot;}core::ptr::null_mut()}
unsafe fn mpc2_read_mpcc_state(mpc:*mut mpc,i:i32,s:*mut mpcc_state){let m=TO_DCN20_MPC(mpc);REG_GET!(m,MPCC_OPP_ID[i],MPCC_OPP_ID,&mut (*s).opp_id);REG_GET!(m,MPCC_TOP_SEL[i],MPCC_TOP_SEL,&mut (*s).dpp_id);REG_GET!(m,MPCC_BOT_SEL[i],MPCC_BOT_SEL,&mut (*s).bot_mpcc_id);REG_GET_4!(m,MPCC_CONTROL[i],MPCC_MODE,&mut (*s).mode,MPCC_ALPHA_BLND_MODE,&mut (*s).alpha_mode,MPCC_ALPHA_MULTIPLIED_MODE,&mut (*s).pre_multiplied_alpha,MPCC_BLND_ACTIVE_OVERLAP_ONLY,&mut (*s).overlap_only);REG_GET_2!(m,MPCC_STATUS[i],MPCC_IDLE,&mut (*s).idle,MPCC_BUSY,&mut (*s).busy);REG_GET!(m,MPCC_OGAM_LUT_RAM_CONTROL[i],MPCC_OGAM_CONFIG_STATUS,&mut (*s).rgam_mode);}

pub unsafe fn dcn20_mpc_construct(m:*mut dcn20_mpc,ctx:*mut dc_context,regs:*const dcn20_mpc_registers,shift:*const dcn20_mpc_shift,mask:*const dcn20_mpc_mask,n:i32){(*m).base.ctx=ctx;(*m).base.funcs=&dcn20_mpc_funcs;(*m).mpc_regs=regs;(*m).mpc_shift=shift;(*m).mpc_mask=mask;(*m).mpcc_in_use_mask=0;(*m).num_mpcc=n;for i in 0..MAX_MPCC{mpc2_init_mpcc(&mut (*m).base.mpcc_array[i],i);}}

static dcn20_mpc_funcs: mpc_funcs = mpc_funcs { read_mpcc_state:mpc2_read_mpcc_state, insert_plane:mpc1_insert_plane, remove_mpcc:mpc1_remove_mpcc, mpc_init:mpc1_mpc_init, mpc_init_single_inst:mpc1_mpc_init_single_inst, update_blending:mpc2_update_blending, cursor_lock:mpc1_cursor_lock, get_mpcc_for_dpp:mpc2_get_mpcc_for_dpp, wait_for_idle:mpc2_assert_idle_mpcc, assert_mpcc_idle_before_connect:mpc2_assert_mpcc_idle_before_connect, init_mpcc_list_from_hw:mpc1_init_mpcc_list_from_hw, set_denorm:mpc2_set_denorm, set_denorm_clamp:mpc2_set_denorm_clamp, set_output_csc:mpc2_set_output_csc, set_ocsc_default:mpc2_set_ocsc_default, set_output_gamma:mpc2_set_output_gamma, power_on_mpc_mem_pwr:mpc20_power_on_ogam_lut, get_mpc_out_mux:mpc1_get_mpc_out_mux, set_bg_color:mpc1_set_bg_color };

